  "Total Spend": { ur: "کل خرچ", ar: "إجمالي الإنفاق", hi: "कुल खर्च", bn: "মোট খরচ", es: "Gasto total", fr: "Dépenses totales", de: "Gesamtausgaben", tr: "Toplam Harcama", zh: "总消费" },
