  "Type and press Enter to add tag": { ur: "ٹیگ شامل کرنے کے لیے لکھیں اور Enter دبائیں", ar: "اكتب واضغط Enter لإضافة وسم", hi: "टैग जोड़ने के लिए लिखें और Enter दबाएं", bn: "ট্যাগ যোগ করতে লিখুন ও Enter চাপুন", es: "Escribe y pulsa Enter para añadir la etiqueta", fr: "Saisissez et appuyez sur Entrée pour ajouter l'étiquette", de: "Tippen und Enter drücken, um ein Tag hinzuzufügen", tr: "Etiket eklemek için yazın ve Enter'a basın", zh: "输入并按 Enter 添加标签" },
  "Unnamed category": { ur: "بے نام کیٹیگری", ar: "فئة بدون اسم", hi: "बिना नाम की श्रेणी", bn: "নামহীন ক্যাটাগরি", es: "Categoría sin nombre", fr: "Catégorie sans nom", de: "Unbenannte Kategorie", tr: "Adsız kategori", zh: "未命名分类" },
  "Untitled file": { ur: "بے عنوان فائل", ar: "ملف بدون عنوان", hi: "बिना शीर्षक वाली फ़ाइल", bn: "শিরোনামহীন ফাইল", es: "Archivo sin título", fr: "Fichier sans titre", de: "Unbenannte Datei", tr: "Başlıksız dosya", zh: "未命名文件" },
  "Updating {route} is not supported by the API.": { ur: "{route} اپ ڈیٹ کرنا API کے ذریعے تعاون یافتہ نہیں ہے۔", ar: "تحديث {route} غير مدعوم من قبل API.", hi: "{route} अपडेट करना API द्वारा समर्थित नहीं है।", bn: "{route} আপডেট করা API দ্বারা সমর্থিত নয়।", es: "Actualizar {route} no es compatible con la API.", fr: "La mise à jour de {route} n'est pas prise en charge par l'API.", de: "Das Aktualisieren von {route} wird von der API nicht unterstützt.", tr: "{route} güncelleme API tarafından desteklenmiyor.", zh: "API 不支持更新 {route}。" },
  "Upload": { ur: "اپ لوڈ کریں", ar: "رفع", hi: "अपलोड करें", bn: "আপলোড করুন", es: "Subir", fr: "Téléverser", de: "Hochladen", tr: "Yükle", zh: "上传" },
  "Upload Date": { ur: "اپ لوڈ کی تاریخ", ar: "تاريخ الرفع", hi: "अपलोड तिथि", bn: "আপলোডের তারিখ", es: "Fecha de subida", fr: "Date de téléversement", de: "Upload-Datum", tr: "Yükleme Tarihi", zh: "上传日期" },
  "Upload media files to view and edit details here.": { ur: "یہاں تفصیلات دیکھنے اور ترمیم کرنے کے لیے میڈیا فائلیں اپ لوڈ کریں۔", ar: "ارفع ملفات الوسائط لعرض التفاصيل وتعديلها هنا.", hi: "यहाँ विवरण देखने और संपादित करने के लिए मीडिया फ़ाइलें अपलोड करें।", bn: "এখানে বিবরণ দেখতে ও সম্পাদনা করতে মিডিয়া ফাইল আপলোড করুন।", es: "Sube archivos multimedia para ver y editar los detalles aquí.", fr: "Téléversez des fichiers multimédias pour afficher et modifier les détails ici.", de: "Laden Sie Mediendateien hoch, um Details hier anzusehen und zu bearbeiten.", tr: "Ayrıntıları burada görüntülemek ve düzenlemek için medya dosyaları yükleyin.", zh: "上传媒体文件以在此处查看和编辑详情。" },
  "Upload media to see details and manage attributes.": { ur: "تفصیلات دیکھنے اور خصوصیات کا انتظام کرنے کے لیے میڈیا اپ لوڈ کریں۔", ar: "ارفع الوسائط لعرض التفاصيل وإدارة السمات.", hi: "विवरण देखने और विशेषताएँ प्रबंधित करने के लिए मीडिया अपलोड करें।", bn: "বিবরণ দেখতে ও বৈশিষ্ট্য পরিচালনা করতে মিডিয়া আপলোড করুন।", es: "Sube medios para ver los detalles y gestionar los atributos.", fr: "Téléversez des médias pour voir les détails et gérer les attributs.", de: "Laden Sie Medien hoch, um Details zu sehen und Attribute zu verwalten.", tr: "Ayrıntıları görmek ve özellikleri yönetmek için medya yükleyin.", zh: "上传媒体以查看详情和管理属性。" },
